import{_ as s,l,o as e,c as d,v as t,p as i,x as o,d as n,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Edmonds 带花树","description":"","frontmatter":{"title":"Edmonds 带花树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/blossom-matching.md","filePath":"cs/blossom-matching.md","lastUpdated":1789023840000}'),p={name:"cs/blossom-matching.md"};function E(c,a,_,u,A,B){const r=l("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="edmonds-带花树" tabindex="-1">Edmonds 带花树 <a class="header-anchor" href="#edmonds-带花树" aria-label="Permalink to &quot;Edmonds 带花树&quot;">​</a></h1><div class="epigraph"><p>非二分图的增广路上可能长出奇环（花）；把花缩成点继续搜，展开后仍是交错增广。</p><footer>—— 据 Edmonds, Paths, Trees, and Flowers, 1965；CLRS 与标准匹配教材整理</footer></div><p>上一课<a href="/cs/hungarian-km">KM 与最大权匹配</a>停在二分。主干匹配课已警告：奇环上「随便交错」会坏。缺口是一般图最大基数匹配：Edmonds 的花（blossom）。不重写二分 HK。后课稳定婚姻换偏好，不是基数匹配。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Berge：匹配最大 \\(\\Leftrightarrow\\) 无增广路，一般图也成立。搜索从自由点长交错树时，若一条非树边连到树上的偶点（相对根的交错距离），则得到奇环：花。把花缩成超点，在收缩图上继续。找到增广则沿花展开还原路径。无增广则当前匹配最大。</p><p>缺口是收缩，不是否定 Berge。朴素实现多项式但常数大；\\(O(VE)\\) 量级可接受；更快的 MV 算法不在本课展开。</p><h3 id="花不是随便一个奇环" tabindex="-1">花不是随便一个奇环 <a class="header-anchor" href="#花不是随便一个奇环" aria-label="Permalink to &quot;花不是随便一个奇环&quot;">​</a></h3><p>花必须是交错树里由基点（花的 LCA 式基）长出的交错奇环。图里随便一个三角形不必立刻缩。收缩保持「有增广 \\(\\Leftrightarrow\\) 原图有增广」的对应。</p><p><span class="marginnote">Edmonds 1965 证明一般图匹配在 P。Gabow、Lawler 给出实现整理。带权一般匹配要带权花，本课只基数。后课 Gale–Shapley 是偏好稳定性，可非二分但问题不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从自由点 BFS/DFS 长交错树。分类邻边：未访则长树；碰到偶点则缩花；碰到另一棵树的自由点则增广。缩花用并查集维护超点。展开按花的奇偶走基点两侧之一。</p>',11)),(e(),i(m,null,{default:o(()=>[h(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FR%5B%22%E8%87%AA%E7%94%B1%E7%82%B9%22%5D%20--%3E%20TREE%5B%22%E4%BA%A4%E9%94%99%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%20BL%5B%22%E5%A5%87%E7%8E%AF%EF%BC%9A%E7%BC%A9%E8%8A%B1%22%5D%0A%20%20TREE%20--%3E%20AUG%5B%22%E5%A2%9E%E5%B9%BF%E8%B7%AF%EF%BC%9A%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20BL%20--%3E%20TREE%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>正确性依赖收缩引理，本课认结论：多项式可求最大匹配。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>奇环上从基点出发两条交错路长度奇偶不同，收缩后把「绕环」变成超点上的普通边，避免搜索在环上死转。二分图无奇环，花不出现，算法退化为匈牙利。与最大流：一般图匹配没有简单的单位二分网络（除非允许指数顶点）。</p><p>不要用「染色看二分」代替花：非二分仍可能有完美匹配。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写带权一般匹配、不写 Tutte 矩阵的代数随机算法细节。不证 Tutte–Berge 公式全文。后课默认：一般图最大基数匹配在 P，算法是带花。下一课稳定婚姻：偏好列表与阻塞对。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一般图增广仍对；奇环用花收缩。</li><li>多项式；二分时无花。</li><li>带权与代数方法不是本课。</li><li>出处：Edmonds, 1965。</li></ul>',8))])}const b=s(p,[["render",E]]);export{T as __pageData,b as default};
